#' Conditional Logistic Regression
#'
#' Conditional logistic regression for matched case-control data: the model is 
#' fitted by the conditional likelihood within the matched sets, as a Cox 
#' model stratified by matched set (the same fit as survival::clogit).
#' 
#'
#' @examples
#' dat <- infert
#' dat$case <- factor(dat$case)
#'
#' condLogReg(data = dat, dep = case, strata = stratum,
#'            covs = vars(spontaneous, induced),
#'            blocks = list(list("spontaneous", "induced")),
#'            refLevels = list(list(var="case", ref="0")),
#'            uniMulti = TRUE)
#'
#' @param data the data as a data frame
#' @param dep a string naming the dependent variable (case/control status)
#'   from \code{data}, variable must be a factor with two levels; the reference
#'   level marks the controls
#' @param strata a string naming the variable that identifies the matched sets
#'   (strata) in \code{data}
#' @param covs a vector of strings naming the covariates from \code{data}
#' @param factors a vector of strings naming the fixed factors from
#'   \code{data}
#' @param blocks a list containing vectors of strings that name the predictors
#'   that are added to the model. The elements are added to the model according
#'   to their order in the list
#' @param refLevels a list of lists specifying reference levels of the
#'   dependent variable and all the factors
#' @param ties \code{'exact'} (default), \code{'efron'} or \code{'breslow'};
#'   the conditional likelihood, exact or approximated. All three are identical
#'   with one case per matched set; the approximations are faster for sets with
#'   many cases
#' @param showNotes \code{TRUE} or \code{FALSE} (default), show the
#'   explanatory notes under the tables; warnings (e.g. predictors that cannot
#'   be estimated) are always shown
#' @param setSummary \code{TRUE} (default) or \code{FALSE}, provide a table of
#'   the composition (cases and controls) of the matched sets
#' @param descTable \code{TRUE} or \code{FALSE} (default), provide a table of
#'   the covariates (mean ± SD) and factors (n, \%) in controls, cases and in
#'   total, with the frequencies of the dependent variable
#' @param modelTest \code{TRUE} or \code{FALSE} (default), provide the model
#'   comparison between the models and the NULL model
#' @param dev \code{TRUE} (default) or \code{FALSE}, provide the deviance (-2
#'   conditional log-likelihood) for the models
#' @param aic \code{TRUE} (default) or \code{FALSE}, provide Akaike's
#'   Information Criterion (AIC) for the models
#' @param bic \code{TRUE} or \code{FALSE} (default), provide Bayesian
#'   Information Criterion (BIC) for the models
#' @param pseudoR2 one or more of \code{'r2mf'}, \code{'r2cs'}, or
#'   \code{'r2n'}; use McFadden's, Cox & Snell, and Nagelkerke pseudo-R²,
#'   respectively
#' @param omni \code{TRUE} or \code{FALSE} (default), provide the omnibus
#'   likelihood ratio tests for the predictors
#' @param uniMulti \code{TRUE} or \code{FALSE} (default), add the odds ratios
#'   of each variable alone (univariable, on the same rows as the model) beside
#'   those of the model (multivariable)
#' @param trend \code{TRUE} or \code{FALSE} (default), p of a trend test for
#'   each factor with three or more levels, the levels scored 1, 2, 3, ... in
#'   their order
#' @param coefDetails \code{TRUE} or \code{FALSE} (default), add the estimate
#'   (log odds ratio), its standard error and Z to the coefficient table
#' @param forest \code{TRUE} or \code{FALSE} (default), a forest plot of the
#'   odds ratios of each model
#' @param ciWidth a number between 50 and 99.9 (default: 95) specifying the
#'   width of the confidence intervals of the odds ratios
#' @param collin \code{TRUE} or \code{FALSE} (default), provide VIF and
#'   tolerance collinearity statistics
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$sets} \tab \tab \tab \tab \tab a table of the composition of the matched sets \cr
#'   \code{results$desc} \tab \tab \tab \tab \tab a table of the covariates (mean ± SD) and factors (n, \%) by the levels of the dependent variable \cr
#'   \code{results$modelFit} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$modelComp} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$models} \tab \tab \tab \tab \tab an array of model specific results \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$sets$asDF}
#'
#' \code{as.data.frame(results$sets)}
#'
#' @export
condLogReg <- function(
    data,
    dep,
    strata,
    covs = NULL,
    factors = NULL,
    blocks = list(
                list()),
    refLevels = NULL,
    ties = "exact",
    showNotes = FALSE,
    setSummary = TRUE,
    descTable = FALSE,
    modelTest = FALSE,
    dev = TRUE,
    aic = TRUE,
    bic = FALSE,
    pseudoR2 = list(
                "r2mf"),
    omni = FALSE,
    uniMulti = FALSE,
    trend = FALSE,
    coefDetails = FALSE,
    forest = FALSE,
    ciWidth = 95,
    collin = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("condLogReg requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(strata)) strata <- jmvcore::resolveQuo(jmvcore::enquo(strata))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(factors)) factors <- jmvcore::resolveQuo(jmvcore::enquo(factors))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(strata), strata, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(factors), factors, NULL))

    for (v in dep) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in factors) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- condLogRegOptions$new(
        dep = dep,
        strata = strata,
        covs = covs,
        factors = factors,
        blocks = blocks,
        refLevels = refLevels,
        ties = ties,
        showNotes = showNotes,
        setSummary = setSummary,
        descTable = descTable,
        modelTest = modelTest,
        dev = dev,
        aic = aic,
        bic = bic,
        pseudoR2 = pseudoR2,
        omni = omni,
        uniMulti = uniMulti,
        trend = trend,
        coefDetails = coefDetails,
        forest = forest,
        ciWidth = ciWidth,
        collin = collin)

    analysis <- condLogRegClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

